/**
 * Registry sources of catalog blocks: the registry item of every Stock catalog asset and its variant props (both from
 * the published registry.buildy.tw/variants/v0.json); prop names, kinds and Lucide icon names come from the published
 * props schemas (registry.buildy.tw/props/v0.json, props-schema.ts). Generated by scripts/registry-snapshot.mjs into
 * sources.json and props.json; nothing here is hand-written data.
 */
import raw from "./sources.json" with { type: "json" };
import type { PageBlockKind } from "@buildytech/page-contract";
import { catalogSnapshot } from "./snapshot.ts";
import { rendererKindForLabel } from "./renderer-kind.ts";
import type { CatalogBlockIndexEntry } from "./types.ts";
import { LUCIDE_ICON_HINT, propShapeFor, propsSummaryFor } from "./props-schema.ts";

/** A registry block of the snapshot (sources.json `blocks`, keyed by registry item name). */
export type RegistryBlock = {
	spec: string;
	/** Block file inside the registry tree (CLI install root), e.g. blocks/feature-grid.svelte. */
	organism: string;
	organismName: string;
	defaultVariant: string;
	/** Published variant props (registry.buildy.tw/variants/v0.json); partial presets, may hold `{"$": ...}` refs. */
	variants: Record<string, Record<string, unknown>>;
};

export type CatalogSources = {
	format: "buildy-catalog-sources";
	version: number;
	registry: string;
	cli: string;
	lockDigest: string;
	variants: { url: string; sha256: string; digest: string };
	/** Pinned registry.buildy.tw/props/v0.json (file sha256 and internal digest). */
	props: { url: string; sha256: string; digest: string };
	initItems: string[];
	npmDependencies: string[];
	/** Registry item graph of the snapshot: type, registryDependencies, npm dependencies and file paths per item. */
	items: Record<string, { type: string; title?: string; registryDependencies: string[]; dependencies: string[]; files: string[] }>;
	/** Skins of the snapshot (registry:theme items, `npx ui8kit add theme-<skin>`): theme-base and skin id -> item, title, CSS file. */
	themes: { base: { item: string; files: string[] } | null; skins: Record<string, { item: string; title: string; file: string }> };
	blocks: Record<string, RegistryBlock>;
	/** Catalog asset id (`block.features/grid`) -> registry item and variant. */
	assets: Record<string, { item: string; variant: string }>;
	/** Catalog spec (`block.features`) -> item and variant used when a block names no variant. */
	specs: Record<string, { item: string; variant: string }>;
};

/** Registry view of one catalog block (spec): its default item and every variant with the item that renders it. */
export type CatalogSourceBlock = {
	spec: string;
	item: string;
	organism: string;
	organismName: string;
	defaultVariant: string;
	variants: Record<string, { item: string; props: Record<string, unknown> }>;
	props: string[];
};

export const catalogSources = raw as unknown as CatalogSources;

/** Registry source of a catalog block (`block.features`), or null when the registry has no item for it. */
export function catalogSourceFor(catalogBlock: string | undefined | null): CatalogSourceBlock | null {
	if (!catalogBlock) return null;
	const first = catalogSources.specs[catalogBlock];
	if (!first) return null;
	const block = catalogSources.blocks[first.item]!;
	const variants: CatalogSourceBlock["variants"] = {};
	for (const [asset, hit] of Object.entries(catalogSources.assets)) {
		if (!asset.startsWith(`${catalogBlock}/`)) continue;
		variants[asset.slice(catalogBlock.length + 1)] = { item: hit.item, props: catalogSources.blocks[hit.item]!.variants[hit.variant]! };
	}
	return {
		spec: catalogBlock,
		item: first.item,
		organism: block.organism,
		organismName: block.organismName,
		defaultVariant: first.variant,
		variants,
		props: propShapeFor(first.item)?.props ?? []
	};
}

/** Catalog block index entry by its spec (`block.features`). */
export function catalogEntryBySpec(spec: string): CatalogBlockIndexEntry | null {
	return catalogSnapshot.blockIndex.find((entry) => entry.spec === spec) ?? null;
}

/** Variants of a catalog block: the pinned catalog index plus the presets of its registry source. */
export function catalogVariantsFor(catalogBlock: string): string[] {
	const entry = catalogEntryBySpec(catalogBlock);
	const source = catalogSourceFor(catalogBlock);
	return [...new Set([...(entry?.variants ?? []), ...Object.keys(source?.variants ?? {})])];
}

/** Available catalog blocks that render as `kind` and have `variant` (catalog data only, pinned snapshot order). */
export function catalogBlocksWithVariant(kind: PageBlockKind, variant: string): string[] {
	return catalogSnapshot.blockIndex
		.filter((entry) => entry.available && rendererKindForLabel(entry.blockId) === kind && catalogVariantsFor(entry.spec).includes(variant))
		.map((entry) => entry.spec);
}

export type CatalogChoiceError = { ok: false; code: "unknown_catalog_block" | "catalog_block_kind_mismatch" | "unknown_variant"; message: string };

/**
 * Normalize and check a catalog block + variant for a block of `kind`. `catalogBlock` may be a spec
 * (`block.features`), a catalog label (`features`) or an asset id (`block.features/grid`, which also names the variant).
 */
export function resolveCatalogChoice(input: {
	kind: PageBlockKind;
	catalogBlock?: string | null;
	variant?: string | null;
}): { ok: true; catalogBlock: string; variant: string | null } | CatalogChoiceError {
	let spec = String(input.catalogBlock ?? "").trim();
	let variant = input.variant == null ? null : String(input.variant).trim() || null;
	const slash = spec.indexOf("/");
	if (slash > 0) {
		variant = variant ?? spec.slice(slash + 1);
		spec = spec.slice(0, slash);
	}
	if (spec && !spec.startsWith("block.")) spec = `block.${spec}`;
	const entry = catalogEntryBySpec(spec);
	if (!entry || !entry.available) {
		return { ok: false, code: "unknown_catalog_block", message: `${spec || "(empty)"} is not a Stock catalog block of the pinned catalog.` };
	}
	if (rendererKindForLabel(entry.blockId) !== input.kind) {
		return {
			ok: false,
			code: "catalog_block_kind_mismatch",
			message: `${spec} renders as ${rendererKindForLabel(entry.blockId) ?? "nothing"}, not ${input.kind}.`
		};
	}
	if (variant !== null && !catalogVariantsFor(spec).includes(variant)) {
		return {
			ok: false,
			code: "unknown_variant",
			message: `${spec} has no variant ${variant}. Variants: ${catalogVariantsFor(spec).join(", ")}.`
		};
	}
	return { ok: true, catalogBlock: spec, variant };
}

function withoutRefs(value: unknown): unknown {
	if (Array.isArray(value)) return value.map(withoutRefs);
	if (typeof value !== "object" || value === null) return value;
	return Object.fromEntries(
		Object.entries(value)
			.filter(([, inner]) => !(typeof inner === "object" && inner !== null && ("$" in inner || ("op" in inner && "args" in inner))))
			.map(([key, inner]) => [key, withoutRefs(inner)])
	);
}

/** Variant props of a catalog block without dictionary refs; the default variant when none is set. */
export function variantProps(catalogBlock: string, variant: string | null | undefined): Record<string, unknown> | null {
	const source = catalogSourceFor(catalogBlock);
	if (!source) return null;
	const preset = source.variants[variant ?? source.defaultVariant] ?? source.variants[source.defaultVariant];
	return preset ? (withoutRefs(preset.props) as Record<string, unknown>) : null;
}

function flat(value: unknown, prefix = ""): Array<[string, string]> {
	if (typeof value !== "object" || value === null || Array.isArray(value)) return [[prefix, String(value)]];
	return Object.entries(value).flatMap(([key, inner]) => flat(inner, prefix ? `${prefix}.${key}` : key));
}

/**
 * Compact model context: the catalog blocks a page block kind can use, each variant as the props that differ from
 * its default variant, the block's row and text fields from its published props schema, and how icons are named
 * (any Lucide kebab-case name, not the list). Generated data; the model picks, the program validates against the schema.
 */
export function modelCatalogSources(only?: readonly string[]): Record<string, unknown> {
	const blocks: Record<string, unknown> = {};
	// Collection turns (ADR 0022): only the collection's catalog blocks; every other block is rejected anyway.
	const keep = only ? new Set(only) : null;
	for (const entry of catalogSnapshot.blockIndex) {
		if (keep && !keep.has(entry.spec)) continue;
		const summary = blockVariantSummary(entry.spec);
		if (summary) blocks[entry.spec] = summary;
	}
	return { blocks, icons: LUCIDE_ICON_HINT };
}

/**
 * One catalog block for the model: its page kind, registry item, default variant, every variant as the props that
 * differ from the default variant, and the row and text fields of its published props schema. Null when the block has
 * no page kind or no registry item.
 */
export function blockVariantSummary(spec: string): {
	kind: PageBlockKind;
	registryItem: string;
	defaultVariant: string;
	variants: Record<string, string>;
	[key: string]: unknown;
} | null {
	const entry = catalogEntryBySpec(spec);
	const kind = entry ? rendererKindForLabel(entry.blockId) : null;
	const source = kind ? catalogSourceFor(spec) : null;
	if (!entry || !kind || !source) return null;
	const base = new Map(flat(variantProps(spec, source.defaultVariant)));
	return {
		kind,
		registryItem: source.item,
		defaultVariant: source.defaultVariant,
		variants: Object.fromEntries(
			Object.keys(source.variants).map((id) => [
				id,
				flat(variantProps(spec, id))
					.filter(([key, value]) => base.get(key) !== value)
					.map(([key, value]) => `${key}=${value}`)
					.join(" ") || "defaults"
			])
		),
		...propsSummaryFor(source.item)
	};
}
